<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import FieldError from '../../../components/FieldError.vue';
import type { PageProps } from '../../../types';

interface Address { recipient_name: string | null; phone: string | null; country_code: string | null; region: string | null; city: string | null; district: string | null; address_line_1: string | null; address_line_2: string | null; postal_code: string | null; reference: string | null }
interface SavedAddress extends Address { id: string; label: string | null }
interface Line { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; base_unit_price: string; discount_unit_amount: string; final_unit_price: string; line_base_total: string; line_discount_total: string; line_total: string; promotion_name: string | null; allocations: { location: string; code: string; quantity: number; status: string }[] }
interface Checkout { id: string; token_hint: string; cart_id: string; status: string; delivery_type: string; currency: string | null; customer_name: string | null; email: string | null; phone: string | null; shipping: Address; billing: Address; subtotal_before_discounts: string; discount_total: string; subtotal: string; shipping_total: string; tax_total: string; grand_total: string; expires_at: string | null; order: { id: string; order_number: string } | null; lines: Line[] }
const props = defineProps<{ checkout: Checkout; addresses: SavedAddress[]; canManage: boolean; canCreateOrder: boolean }>();
const page = usePage<PageProps>();
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const pending = computed(() => props.checkout.status === 'PENDING');
const cancellable = computed(() => ['PENDING', 'READY'].includes(props.checkout.status));
const form = useForm({ customer_name: props.checkout.customer_name ?? '', email: props.checkout.email ?? '', phone: props.checkout.phone ?? '', delivery_type: props.checkout.delivery_type, shipping_address_id: '', billing_address_id: '', billing_same_as_shipping: false, ...Object.fromEntries(Object.entries(props.checkout.shipping).map(([key, value]) => [`shipping_${key}`, value ?? ''])), ...Object.fromEntries(Object.entries(props.checkout.billing).map(([key, value]) => [`billing_${key}`, value ?? ''])) });
const save = () => form.patch(`/admin/checkouts/${props.checkout.id}`, { preserveScroll: true });
const prepare = () => router.post(`/admin/checkouts/${props.checkout.id}/prepare`, {}, { preserveScroll: true });
const cancel = () => { if (window.confirm('Cancel this checkout and release all active reservations?')) router.post(`/admin/checkouts/${props.checkout.id}/cancel`, {}, { preserveScroll: true }); };
const createOrder = () => router.post(`/admin/checkouts/${props.checkout.id}/order`, {}, { preserveScroll: true });
const money = (amount: string) => `${props.checkout.currency ?? ''} ${amount}`.trim();
const fields: { key: keyof Address; label: string }[] = [{ key: 'recipient_name', label: 'Recipient' }, { key: 'phone', label: 'Phone' }, { key: 'country_code', label: 'Country' }, { key: 'region', label: 'Region' }, { key: 'city', label: 'City' }, { key: 'district', label: 'District' }, { key: 'address_line_1', label: 'Address line 1' }, { key: 'address_line_2', label: 'Address line 2' }, { key: 'postal_code', label: 'Postal code' }, { key: 'reference', label: 'Reference' }];
</script>

<template>
    <Head :title="`Checkout ${checkout.token_hint}`" /><AdminLayout><section>
        <div class="flex flex-wrap items-end justify-between gap-5"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ checkout.status }} / {{ checkout.delivery_type }}</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">Checkout {{ checkout.token_hint }}</h1><p v-if="checkout.expires_at" class="mt-3 text-sm text-[#637067]">Expires {{ new Date(checkout.expires_at).toLocaleString() }}</p></div><div class="flex flex-wrap gap-3"><Link v-if="checkout.order" :href="`/admin/orders/${checkout.order.id}`" class="bg-emerald-800 px-4 py-3 text-sm font-semibold text-white">Order {{ checkout.order.order_number }}</Link><button v-else-if="canCreateOrder && checkout.status === 'READY'" class="bg-emerald-800 px-4 py-3 text-sm font-semibold text-white" @click="createOrder">Create order</button><button v-if="canManage && cancellable" class="border border-red-800 px-4 py-3 text-sm font-semibold text-red-800" @click="cancel">Cancel checkout</button><Link href="/admin/checkouts" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Back</Link></div></div>
        <form v-if="pending && canManage" class="mt-8 border border-[#17211b]/15 bg-white p-6" @submit.prevent="save"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Contact and delivery snapshot</p><div class="mt-5 grid gap-4 sm:grid-cols-3"><label class="text-sm font-semibold">Name<input v-model="form.customer_name" class="mt-2 w-full border px-3 py-2" /></label><label class="text-sm font-semibold">Email<input v-model="form.email" type="email" class="mt-2 w-full border px-3 py-2" /></label><label class="text-sm font-semibold">Phone<input v-model="form.phone" class="mt-2 w-full border px-3 py-2" /></label></div>
            <div class="mt-6"><label class="text-sm font-semibold">Delivery type<select v-model="form.delivery_type" class="ml-3 border px-3 py-2"><option value="SHIPPING">Shipping</option><option value="PICKUP">Pickup</option></select></label></div>
            <FieldError :message="serverErrors.contact" /><div v-if="form.delivery_type === 'SHIPPING'" class="mt-6 grid gap-6 lg:grid-cols-2"><fieldset><legend class="font-semibold">Shipping address</legend><select v-if="addresses.length" v-model="form.shipping_address_id" class="mt-3 w-full border px-3 py-2"><option value="">Manual address</option><option v-for="address in addresses" :key="address.id" :value="address.id">{{ address.label ?? address.address_line_1 }}</option></select><div class="mt-3 grid gap-3 sm:grid-cols-2"><label v-for="field in fields" :key="`shipping_${field.key}`" class="text-xs font-semibold">{{ field.label }}<input v-model="form[`shipping_${field.key}` as keyof typeof form]" class="mt-1 w-full border px-3 py-2 text-sm" /></label></div></fieldset>
                <fieldset><legend class="font-semibold">Billing address</legend><label class="mt-3 block text-sm"><input v-model="form.billing_same_as_shipping" type="checkbox" /> Same as shipping</label><select v-if="addresses.length && !form.billing_same_as_shipping" v-model="form.billing_address_id" class="mt-3 w-full border px-3 py-2"><option value="">Manual or empty</option><option v-for="address in addresses" :key="address.id" :value="address.id">{{ address.label ?? address.address_line_1 }}</option></select><div v-if="!form.billing_same_as_shipping" class="mt-3 grid gap-3 sm:grid-cols-2"><label v-for="field in fields" :key="`billing_${field.key}`" class="text-xs font-semibold">{{ field.label }}<input v-model="form[`billing_${field.key}` as keyof typeof form]" class="mt-1 w-full border px-3 py-2 text-sm" /></label></div></fieldset></div>
            <div class="mt-6 flex gap-3"><button :disabled="form.processing" class="border border-[#17211b] px-5 py-3 text-sm font-semibold">Save details</button><button type="button" class="bg-[#17211b] px-5 py-3 text-sm font-semibold text-white" @click="prepare">Prepare and reserve</button></div><FieldError :message="serverErrors.checkout ?? serverErrors.shipping ?? serverErrors.cart ?? serverErrors.inventory" /></form>
        <div class="mt-8 grid gap-4 sm:grid-cols-3"><article v-for="item in [['Before discounts', checkout.subtotal_before_discounts], ['Discount', checkout.discount_total], ['Grand total', checkout.grand_total]]" :key="item[0]" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><p class="text-xs uppercase text-[#637067]">{{ item[0] }}</p><p class="mt-2 font-mono text-xl font-semibold">{{ money(item[1]) }}</p></article></div>
        <section class="mt-10"><h2 class="text-3xl font-semibold">Snapshot lines</h2><div class="mt-5 grid gap-4"><article v-for="line in checkout.lines" :key="line.id" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><div class="flex flex-wrap justify-between gap-5"><div><h3 class="text-xl font-semibold">{{ line.product_name }}</h3><p class="text-sm text-[#637067]">{{ line.variant_name }} / {{ line.sku }} / Qty {{ line.quantity }}</p><p v-if="line.promotion_name" class="mt-2 text-sm font-semibold text-emerald-800">{{ line.promotion_name }}</p></div><dl class="grid grid-cols-3 gap-5 text-sm"><div><dt>Base</dt><dd class="font-mono">{{ money(line.base_unit_price) }}</dd></div><div><dt>Discount</dt><dd class="font-mono">{{ money(line.discount_unit_amount) }}</dd></div><div><dt>Total</dt><dd class="font-mono font-semibold">{{ money(line.line_total) }}</dd></div></dl></div><div v-if="line.allocations.length" class="mt-4 flex flex-wrap gap-2"><span v-for="allocation in line.allocations" :key="allocation.code" class="bg-emerald-100 px-3 py-1 text-xs font-semibold">{{ allocation.code }}: {{ allocation.quantity }} ({{ allocation.status }})</span></div></article><p v-if="!checkout.lines.length" class="border border-dashed p-8 text-center text-[#637067]">Lines are created during prepare.</p></div></section>
    </section></AdminLayout>
</template>
